export function evaluate({ inputs, time, seed, state }) {
  const { launchSpeed, gravity, mass } = inputs;
  const t = time; // seconds since launch
  // physics
  const velocity = launchSpeed - gravity * t;
  const acceleration = -gravity;
  const force = mass * gravity;
  const height = launchSpeed * t - gravity * t * t / 2;
  const apexTime = launchSpeed / gravity;
  const apexHeight = launchSpeed * launchSpeed / (2 * gravity);
  // motion state
  let motionState = "Rising";
  if (t < 0) motionState = "Before launch";
  else if (Math.abs(t - apexTime) < 1e-6) motionState = "At the top";
  else if (t > apexTime) motionState = "Falling";
  // layout constants
  const laneX = 20, laneY = 20, laneW = 300, laneH = 380;
  const plotX = 340, plotY = 20, plotW = 280, plotH = 380;
  // panel (lane)
  const laneObjs = sdk.panel({x: laneX, y: laneY, w: laneW, h: laneH, title: "Motion", state: motionState, id: "lane.main"});
  // ball position on ruler (0 to 2.2 m mapped to lane height)
  const rulerMin = 0, rulerMax = 2.2;
  const ballY = laneY + laneH - ((height - rulerMin) / (rulerMax - rulerMin)) * laneH;
  const ball = sdk.circle("ball.toss", laneX + laneW/2, ballY, 24, {role:"neutral"});
  // velocity arrow (blue, length proportional to |v|, direction up for positive)
  const velScale = 10; // pixels per m/s
  const velLen = Math.abs(velocity) * velScale;
  const velDir = velocity >= 0 ? "up" : "down";
  const velArrow = sdk.vector("vec.v", {x: ball[0].x, y: ball[0].y}, {value: velLen, direction: velDir}, {scale:1, label:"v", role:"output"});
  // acceleration arrow (dashed warm, constant magnitude)
  const accScale = 8;
  const accLen = Math.abs(acceleration) * accScale;
  const accDir = acceleration >= 0 ? "up" : "down";
  const accArrow = sdk.vector("vec.a", {x: ball[0].x, y: ball[0].y}, {value: accLen, direction: accDir}, {scale:1, label:"a", role:"output", style:"dashed"});
  // callout with lines for v, a, F
  const calloutLines = [];
  calloutLines.push(sdk.text("callout.toss.v", 0, 0, `${sdk.format(velocity,3)} m/s`));
  calloutLines.push(sdk.text("callout.toss.a", 0, 0, `${sdk.format(acceleration,3)} m/s²`));
  calloutLines.push(sdk.text("callout.toss.F", 0, 0, `${sdk.format(force,3)} N`));
  const callout = sdk.callout(ball[0].x + 30, ball[0].y - 30, calloutLines, {id:"callout.toss"});
  // velocity‑time plot
  const plotXDomain = [0, Math.max(apexTime*2, 1.8)];
  const plotYDomain = [-5.5, 5.5];
  const points = [];
  const sampleCount = 24;
  for (let i=0;i<=sampleCount;i++){
    const tt = plotXDomain[0] + (plotXDomain[1]-plotXDomain[0])*i/sampleCount;
    const vv = launchSpeed - gravity*tt;
    points.push({x:tt, y:vv});
  }
  const plot = sdk.plot("plot.vt", {
    x: plotX, y: plotY, w: plotW, h: plotH,
    xDomain: {min: plotXDomain[0], max: plotXDomain[1]},
    yDomain: {min: plotYDomain[0], max: plotYDomain[1]},
    xLabel: "t (s)", yLabel: "v (m/s)",
    series: [{id:"series.v", label:"v", kind:"line", points}]
  });
  // marker for current time
  const markerX = ((t - plotXDomain[0])/(plotXDomain[1]-plotXDomain[0]))*plotW + plotX;
  const marker = sdk.line("marker.time", markerX, plotY, markerX, plotY+plotH, {role:"output"});
  // assemble objects
  const objects = [];
  objects.push(...laneObjs);
  objects.push(ball[0]);
  objects.push(velArrow[0]);
  objects.push(accArrow[0]);
  objects.push(...callout);
  objects.push(plot[0]);
  objects.push(marker[0]);
  // readouts
  const readouts = [
    {id:"velocity", value: velocity},
    {id:"acceleration", value: acceleration},
    {id:"force", value: force},
    {id:"motionState", value: motionState}
  ];
  return {frame: {width: 640, height: 420, objects, readouts}, quantities: {launchSpeed, gravity, mass, apexTime, apexHeight, height, velocity, acceleration, force}};
}
